<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {apiClient} from '../../api/client'
type Asset={platform:string;arch:string;name:string;url:string;size_bytes:number;sha256:string}
type Release={id:number;version:string;channel:string;status:string;notes:string;assets:Asset[];required_targets:string[]}
const admin=window.location.pathname.includes('/admin/')
const allowed=ref(false),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),progress=ref(0)
const releases=ref<Release[]>([]),current=ref<Release|null>(null),selected=ref<Release|null>(null)
const version=ref(''),notes=ref(''),targets=ref(['macos/universal','windows/x64']),reason=ref('')
const names:Record<string,string>={'macos/universal':'macOS · Apple 芯片与 Intel','windows/x64':'Windows · 64 位','macos/arm64':'macOS · Apple 芯片','macos/x64':'macOS · Intel'}
const statuses:Record<string,string>={draft:'草稿',ready:'校验通过',published:'已发布',withdrawn:'已撤回'}
const size=(n:number)=>`${(n/1024/1024).toFixed(1)} MB`
function message(e:any){return e?.response?.data?.message||e?.message||'操作失败，请稍后重试'}
async function load(){
 const data=(await apiClient.get('/client-updates/public')).data;current.value=data.release
 if(admin){allowed.value=(await apiClient.get('/client-updates/access')).data.is_admin===true;if(allowed.value){releases.value=(await apiClient.get('/client-updates/admin/releases')).data;if(selected.value)selected.value=releases.value.find(r=>r.id===selected.value!.id)||null}}
}
async function work(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await load()}catch(e){error.value=message(e)}finally{busy.value=false;progress.value=0}}
onMounted(async()=>{try{await load()}catch(e){error.value=message(e)}finally{loading.value=false}})
async function create(){await work(async()=>{selected.value=(await apiClient.post('/client-updates/admin/releases',{version:version.value,notes:notes.value,required_targets:targets.value})).data;notice.value='草稿已创建，请上传各平台安装包。'})}
async function upload(event:Event,target:string){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!selected.value)return;const r=selected.value,[platform,arch]=target.split('/');const name=`CodexPlusPlus-${r.version}-${platform}-${arch}${platform==='macos'?'.dmg':file.name.toLowerCase().endsWith('.msi')?'.msi':'-setup.exe'}`;await work(async()=>{selected.value=(await apiClient.post(`/client-updates/admin/releases/${r.id}/assets`,file,{params:{platform,arch,name},headers:{'Content-Type':'application/octet-stream'},onUploadProgress:e=>{progress.value=e.total?Math.round(e.loaded/e.total*100):0}})).data;notice.value='安装包上传完成，导出清单后在本机或 CI 签名。'})}
async function exportManifest(){if(!selected.value)return;await work(async()=>{const {data}=await apiClient.get(`/client-updates/admin/releases/${selected.value!.id}/manifest`);const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='client-release-manifest.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='清单已导出。签名后上传 signed.json 校验。'})}
async function validate(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!selected.value)return;await work(async()=>{if(file.size>256*1024)throw Error('签名清单过大');selected.value=(await apiClient.post(`/client-updates/admin/releases/${selected.value!.id}/validate`,JSON.parse(await file.text()))).data;notice.value='签名与安装包摘要均已通过校验，可以发布。'})}
async function publish(){if(!selected.value)return;await work(async()=>{await apiClient.post(`/client-updates/admin/releases/${selected.value!.id}/publish`);notice.value='发布完成，官网和客户端已使用此版本。'})}
async function withdraw(){if(!selected.value)return;await work(async()=>{await apiClient.post(`/client-updates/admin/releases/${selected.value!.id}/withdraw`,{reason:reason.value});notice.value='版本已撤回，将停止新的下载与更新。';reason.value=''})}
async function copy(hash:string){try{await navigator.clipboard.writeText(hash);notice.value='SHA-256 已复制'}catch{error.value='复制失败，请手动选择摘要复制'}}
</script>
<template>
<div class="client-release-page">
 <header><a class="brand" href="/fastaiui/downloads/codexplus"><span>F</span> FastAiApi <small>客户端</small></a><nav><a href="/fastaiui/recharge">充值中心</a><a v-if="admin" href="/fastaiui/downloads/codexplus">下载页面 ↗</a><a v-else href="/fastaiui/admin/client-releases">版本管理</a></nav></header>
 <main>
  <section class="hero"><div><span class="eyebrow">FASTAIAPI · {{admin?'RELEASE CENTER':'DESKTOP CLIENT'}}</span><h1>{{admin?'客户端版本发布':'把创作带到你的桌面'}}</h1><p>{{admin?'从草稿到发布，安装包与更新清单统一管理。':'FastAiApi 定制 Codex++，连接模型服务，专注每一次创作。'}}</p></div><span class="version-chip">{{current?'稳定版 '+current.version:'暂未发布正式版本'}}</span></section>
  <p v-if="loading" class="notice" role="status">正在加载版本信息…</p><p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
  <template v-if="!admin">
   <section v-if="current" class="download-grid"><article v-for="asset in current.assets" :key="asset.name" class="panel download-card"><span class="platform-icon">{{asset.platform==='macos'?'⌘':'⊞'}}</span><h2>{{names[asset.platform+'/'+asset.arch]}}</h2><p>v{{current.version}} · {{size(asset.size_bytes)}}</p><a class="primary" :href="asset.url">下载安装包 ↓</a><details><summary>文件校验</summary><code>{{asset.sha256}}</code><button @click="copy(asset.sha256)">复制 SHA-256</button></details></article></section>
   <section v-else-if="!loading&&!error" class="panel empty"><h2>客户端安装包准备中</h2><p>正式版本发布后，安装包和版本说明将在这里同步展示。</p></section>
   <section v-if="current" class="panel release-notes"><span class="eyebrow">WHAT'S NEW</span><h2>版本更新说明</h2><p>{{current.notes||'本版本包含体验优化与问题修复。'}}</p></section>
   <section class="footnote"><p>已安装的旧版用户，请先从这里下载安装一次新版，后续即可在客户端内接收 FastAiApi 更新。</p><p>需要帮助？QQ：172733456 · 微信：selectthree</p></section>
  </template>
  <template v-else-if="allowed">
   <section class="admin-grid"><aside class="panel"><div class="panel-heading"><h2>发布记录</h2><span>{{releases.length}} 个版本</span></div><div class="release-list"><button v-for="r in releases" :key="r.id" :class="{active:selected?.id===r.id}" @click="selected=r"><strong>v{{r.version}}</strong><span class="status" :class="r.status">{{statuses[r.status]}}</span><small>stable · {{r.assets.length}} 个安装包</small></button><p v-if="!releases.length" class="muted">还没有发布记录，从创建草稿开始。</p></div></aside>
   <div class="workspace"><form class="panel create-form" @submit.prevent="create"><div class="panel-heading"><h2>创建新版本</h2><span>稳定渠道</span></div><div class="form-content"><label>版本号<input v-model="version" required pattern="(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)" placeholder="例如 1.11.3"/></label><label>发布说明<textarea v-model="notes" maxlength="16000" rows="3" placeholder="向用户介绍本次更新"/></label><fieldset><legend>本次发布的平台</legend><label v-for="(name,target) in {'macos/universal':names['macos/universal'],'macos/arm64':names['macos/arm64'],'windows/x64':names['windows/x64']}" :key="target" class="target"><input type="checkbox" v-model="targets" :value="target"/>{{name}}</label></fieldset><button class="primary" :disabled="busy||!targets.length">创建草稿</button></div></form>
   <section v-if="selected" class="panel editor"><div class="panel-heading"><h2>v{{selected.version}}</h2><span class="status" :class="selected.status">{{statuses[selected.status]}}</span></div><div class="form-content"><p class="notes-preview">{{selected.notes||'暂无发布说明'}}</p><div v-for="target in selected.required_targets" :key="target" class="asset-row"><div><strong>{{names[target]}}</strong><small>{{selected.assets.find(a=>a.platform+'/'+a.arch===target)?size(selected.assets.find(a=>a.platform+'/'+a.arch===target)!.size_bytes):'等待上传'}}</small></div><label v-if="selected.status==='draft'" class="upload-button">{{selected.assets.some(a=>a.platform+'/'+a.arch===target)?'重新上传':'上传安装包'}}<input type="file" :disabled="busy" :accept="target.startsWith('macos')?'.dmg':'.exe,.msi'" @change="upload($event,target)"/></label><span v-else class="status ready">已校验</span></div><progress v-if="busy&&progress" max="100" :value="progress"/>
    <div v-if="selected.status==='draft'" class="signing"><h3>签名后发布</h3><p>安装包齐备后导出清单，在受信任的本机或 CI 签名，再上传签名清单。私钥无需上传网站。</p><button :disabled="busy||!selected.assets.length" @click="exportManifest">① 导出待签名清单</button><label class="upload-button">② 上传签名清单并校验<input type="file" accept=".json" :disabled="busy" @change="validate"/></label><code>go run scripts/client-release.go sign --key &lt;私钥路径&gt; --manifest client-release-manifest.json --out signed.json</code></div>
    <button v-if="selected.status==='ready'" class="primary" :disabled="busy" @click="publish">发布到官网与客户端</button>
    <div v-if="['ready','published'].includes(selected.status)" class="withdraw"><label>撤回原因<input v-model="reason" maxlength="500" placeholder="填写原因，撤回后停止新的分发"/></label><button :disabled="busy||reason.trim().length<2" @click="withdraw">撤回此版本</button></div>
   </div></section></div></section>
  </template>
  <section v-else-if="admin&&!loading" class="panel empty"><h2>需要管理员权限</h2><p>请先使用本站管理员账号登录后打开版本管理。</p><a class="primary" href="/login">前往登录</a></section>
 </main><footer>FastAiApi · 自有站点分发 · 签名与 SHA-256 校验</footer>
</div>
</template>
<style scoped>
.client-release-page{min-height:100vh;background:#f5f8f9;color:#203641;font:14px/1.6 system-ui,sans-serif}.client-release-page *{box-sizing:border-box}header{height:76px;padding:0 max(24px,calc((100vw - 1180px)/2));display:flex;justify-content:space-between;align-items:center;background:white;border-bottom:1px solid #e4ecec}.brand{display:flex;gap:10px;align-items:center;font-weight:700;color:#163e3a;text-decoration:none;font-size:19px}.brand>span{display:grid;place-items:center;width:34px;height:34px;background:#1aaa91;color:white;border-radius:11px}.brand small{font-size:12px;color:#81948f;font-weight:500}nav{display:flex;gap:22px}a{color:#168d78;text-decoration:none}main{max-width:1180px;padding:48px 24px;margin:auto}.hero{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:34px}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:700;color:#229b87}h1{font-size:34px;letter-spacing:-1px;margin:10px 0}h2{font-size:17px;margin:0}p{color:#7d8e98}.hero p{margin:0}.version-chip,.status{display:inline-flex;align-items:center;white-space:nowrap;padding:5px 10px;border-radius:6px;background:#e7f6f0;color:#248d75;font-size:11px}.panel{border:1px solid #dfe8e8;border-radius:16px;background:white;overflow:hidden}.download-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}.download-card{padding:30px}.platform-icon{display:grid;place-items:center;width:58px;height:58px;border-radius:16px;background:#edf7f4;color:#168d78;font-size:30px;margin-bottom:24px}.download-card p{font-size:12px}.primary{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;border-radius:9px;background:#168f7b;color:white;border:0;cursor:pointer;font:inherit;font-weight:600}.download-card .primary{width:100%;margin:12px 0}.download-card details{font-size:11px;color:#83949d;margin-top:10px}.download-card code{display:block;overflow-wrap:anywhere;margin:8px 0}.release-notes{padding:28px;margin-top:24px}.release-notes p,.notes-preview{white-space:pre-wrap}.footnote{font-size:12px;padding:20px 0}.notice{padding:13px 16px;border:1px solid #b5e1d6;background:#eaf8f2;border-radius:9px;color:#287d65}.error{background:#fff1ed;border-color:#f2ccbf;color:#ad533e}.empty{text-align:center;padding:50px}.admin-grid{display:grid;grid-template-columns:270px minmax(0,1fr);gap:24px}.admin-grid aside{align-self:start}.panel-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:18px 22px;border-bottom:1px solid #edf1f2}.panel-heading>span:not(.status){font-size:11px;color:#8a9ca5}.release-list{padding:10px}.release-list button{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;width:100%;padding:14px;text-align:left;background:transparent;border:1px solid transparent;border-radius:9px;cursor:pointer;color:inherit}.release-list button.active{border-color:#46b29e;background:#f0faf6}.release-list small{width:100%;font-size:10px;color:#82949a}.workspace{display:grid;gap:24px;min-width:0}.form-content{padding:22px;display:grid;gap:18px}label{display:grid;gap:7px;font-size:12px}input:not([type=checkbox]),textarea{width:100%;padding:11px 12px;border:1px solid #dce6e5;border-radius:8px;font:inherit;color:inherit;background:white}textarea{resize:vertical}fieldset{border:0;padding:0;margin:0}legend{font-size:12px;margin-bottom:8px}.target{display:inline-flex;align-items:center;gap:7px;margin-right:18px}.asset-row{display:flex;gap:16px;justify-content:space-between;align-items:center;padding:14px;border:1px solid #e5eeeb;border-radius:9px}.asset-row strong{font-size:12px}.asset-row small{display:block;color:#81969a;font-size:11px}.upload-button,button:not(.primary):not(.release-list button){display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid #cfe1da;background:#f5faf7;border-radius:7px;padding:9px 12px;font:inherit;font-size:11px;color:#36836d;cursor:pointer}.upload-button{position:relative;overflow:hidden}.upload-button input{position:absolute;inset:0;opacity:0;cursor:pointer}.signing{border:1px dashed #c7dcd4;border-radius:10px;padding:18px;display:flex;flex-wrap:wrap;gap:10px}.signing h3{width:100%;margin:0;font-size:13px}.signing p{font-size:11px;margin:0 0 6px;width:100%}.signing code{display:block;overflow-wrap:anywhere;font-size:10px;color:#6e8585}.withdraw{border-top:1px solid #edf0ef;padding-top:18px;display:grid;gap:10px}.status.draft{background:#eef2f6;color:#728595}.status.withdrawn{background:#fceee8;color:#b87858}.muted{padding:12px;font-size:12px}.notes-preview{margin:0;font-size:12px}button:disabled,input:disabled{opacity:.5;cursor:default}progress{width:100%;accent-color:#168f7b}footer{text-align:center;font-size:10px;color:#8da19e;padding:24px}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid #22a98e;outline-offset:3px}@media(max-width:760px){.admin-grid{grid-template-columns:1fr}.hero{align-items:flex-start;flex-direction:column}h1{font-size:28px}main{padding:28px 16px}header{padding:0 16px}nav{font-size:11px;gap:12px}.panel-heading,.form-content{padding:16px}.brand small{display:none}}
</style>
